import { Injectable, OnModuleInit } from '@nestjs/common';
import { PrismaClient } from '@prisma/client';

@Injectable()
export class PrismaService extends PrismaClient implements OnModuleInit {
  async onModuleInit() {
    await this.$connect();
  }
}

Почему: у Nest нет первоклассного Prisma DI, поэтому PrismaService — это обёртка, которую предоставляешь ТЫ. Он должен реализовывать OnModuleInit и вызывать await this.$connect() в onModuleInit — lifecycle-хуке, выполняемом, когда модуль инициализирован, — именно там открывается подключение к базе. Без этого клиент инжектится, но никогда не подключается, поэтому первый вызов this.prisma.user.* падает. (В новых версиях Prisma открывает подключение лениво при первом запросе, но рецепт всё равно вешает $connect в onModuleInit, чтобы подключение — и любая ошибка — всплывало на старте, а не посреди запроса.)
